"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:1214-01-01:0":{"b": ["უკანასკნელი გურხანი იელუ ჩელუგუ ტახტიდან ჩამოგდებიდან სამი წლის შემდეგ გარდაიცვალა", "8ea5be30"], "d": ["ყარახიტაის სახელმწიფოს 1178 წლიდან მმართველი გურხანი იელუ ჩელუგუ, 1211 წელს სიძე ნაიმან ქუჩლუგ ყაენის მიერ ტყვედ აყვანისა და სახელმწიფოს მოსპობის შემდეგაც, ბატონობას ფაქტობრივად აგრძელებდა და 1214 წელს გარდაიცვალა; ყარახიტაის ყველა მიწა ნაიმანების ხელში გადავიდა.", "d94ee478"]},
